pub struct Parsed {
    source: String,
    name: Range<usize>,
}

impl Parsed {
    pub fn new(source: String, name: Range<usize>) -> Self {
        assert!(name.end <= source.len());
        assert!(source.is_char_boundary(name.start));
        assert!(source.is_char_boundary(name.end));
        Self { source, name }
    }

    pub fn name(&self) -> &str {
        &self.source[self.name.clone()]
    }

    pub fn source(&self) -> &str {
        &self.source
    }
}
```

