```rust
use nom::{
    branch::alt,
    bytes::complete::tag,
    character::complete::{digit1, multispace0},
    combinator::map_res,
    multi::many0,
    sequence::{delimited, pair},
    IResult,
};

#[derive(Debug)]
enum Expr {
    Num(i64),
    BinOp(Box<Expr>, char, Box<Expr>),
}

fn ws<'a, F, O>(inner: F) -> impl FnMut(&'a str) -> IResult<&'a str, O>
where
    F: FnMut(&'a str) -> IResult<&'a str, O>,
{
    delimited(multispace0, inner, multispace0)
}

fn number(input: &str) -> IResult<&str, Expr> {
    map_res(ws(digit1), |s: &str| s.parse::<i64>().map(Expr::Num))(input)
}

fn add_op(input: &str) -> IResult<&str, char> {
    let (rest, op) = ws(alt((tag("+"), tag("-"))))(input)?;
    Ok((rest, op.chars().next().unwrap()))
}

fn expr(input: &str) -> IResult<&str, Expr> {
    let (rest, first) = number(input)?;
    let (rest, ops) = many0(pair(add_op, number))(rest)?;
    // Skládání zleva pro obnovení levé asociativity
    let result = ops.into_iter().fold(first, |acc, (op, rhs)| {
        Expr::BinOp(Box::new(acc), op, Box::new(rhs))
    });
    Ok((rest, result))
}
```

Klíčový poznatek: parse tree z `term (('+' | '-') term)*` je přirozeně rovnoměrný seznam, a skládáte jej zleva během konstrukce AST. `1 - 2 - 3` se parsovalo jako `[1, (-, 2), (-, 3)]` a skládá se do `((1 - 2) - 3)`, což je to, co chcete pro odčítání.

Pokud skutečně potřebujete přijímat levě rekursivní gramatiky tak, jak jsou napsány, podívejte se na `lalrpop` (generátor LALR(1)) nebo memoizující PEG knihovny — ale pro jazyk výrazů je iterativní forma to, co skutečně ručně psané produkční parsery (rustc, clang, V8 parser) dělají.

